import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Primeros pasos","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/getting-started.md","filePath":"es-ES/user-guide/getting-started.md","lastUpdated":1787982919000}'),r={name:"es-ES/user-guide/getting-started.md"};function n(s,e,d,l,c,u){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="primeros-pasos" tabindex="-1">Primeros pasos <a class="header-anchor" href="#primeros-pasos" aria-label="Permalink to &quot;Primeros pasos&quot;">​</a></h1><p>¡Te damos la bienvenida a Lertaro! Lertaro es un lanzador de búsqueda de archivos ultrarrápido y una herramienta de productividad diseñada a medida para Windows. Esta guía te explica las opciones de instalación, la arquitectura principal, las tres modalidades de ventana y las operaciones de búsqueda esenciales.</p><h2 id="_1-descarga-e-instalacion" tabindex="-1">1. Descarga e instalación <a class="header-anchor" href="#_1-descarga-e-instalacion" aria-label="Permalink to &quot;1. Descarga e instalación&quot;">​</a></h2><p>Puedes obtener la última versión en la página principal oficial. Cada versión publicada ofrece instalador y paquete portable para aplicaciones compiladas de forma nativa tanto para <strong>x64</strong> como para <strong>ARM64</strong>:</p><h3 id="paquete-de-instalacion-lertaro-setup-exe-recomendado" tabindex="-1">Paquete de instalación (<code>Lertaro-Setup.exe</code>, recomendado) <a class="header-anchor" href="#paquete-de-instalacion-lertaro-setup-exe-recomendado" aria-label="Permalink to &quot;Paquete de instalación (`Lertaro-Setup.exe`, recomendado)&quot;">​</a></h3><ul><li><strong>Configuración automatizada</strong>: El asistente registra automáticamente el servicio de indexación en segundo plano (<code>Lertaro.Service</code>), configura el inicio automático y detecta e instala el entorno de ejecución de escritorio de .NET necesario.</li><li><strong>Actualizaciones sencillas</strong>: Admite comprobación automática de actualizaciones e instalación directa con un solo clic.</li></ul><h3 id="edicion-portatil-lertaro-portable-zip" tabindex="-1">Edición portátil (<code>Lertaro-Portable.zip</code>) <a class="header-anchor" href="#edicion-portatil-lertaro-portable-zip" aria-label="Permalink to &quot;Edición portátil (`Lertaro-Portable.zip`)&quot;">​</a></h3><ul><li><strong>Descomprimir y usar</strong>: Descomprime en cualquier carpeta y ejecútalo inmediatamente sin necesidad de instalación formal.</li><li><strong>Dependencias de entorno</strong>: Si tu sistema no cuenta con el entorno de ejecución de escritorio de .NET, ejecuta el script <code>install-dotnet-runtime.bat</code> incluido en el directorio descomprimido.</li><li><strong>Aislamiento de datos</strong>: La versión portátil guarda los datos globales del equipo en <code>Data\\Machine</code> junto al ejecutable, y las configuraciones de usuario en <code>Data\\Users\\&lt;SID hash&gt;</code>. Si el directorio <code>Data</code> aún no existe, leerá <code>%ProgramData%\\Lertaro</code> y <code>%LocalAppData%\\Lertaro</code> por compatibilidad; una vez creado, priorizará los datos locales como un entorno completamente autónomo.</li><li><strong>Desinstalación limpia</strong>: Antes de eliminar la carpeta portátil, ejecuta el script <code>portable-cleanup.bat</code>. Este detiene y desinstala el servicio en segundo plano, y elimina los registros URI <code>lertaro://</code> y las entradas de inicio del usuario actual.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Si utilizas un dispositivo Windows on ARM (como Surface Pro X o portátiles con Snapdragon), descarga la versión nativa <code>Lertaro-Setup-arm64.exe</code> o <code>Lertaro-Portable-arm64.zip</code> para obtener el mejor rendimiento y eficiencia energética.</p></div><h2 id="_2-descripcion-de-la-arquitectura" tabindex="-1">2. Descripción de la arquitectura <a class="header-anchor" href="#_2-descripcion-de-la-arquitectura" aria-label="Permalink to &quot;2. Descripción de la arquitectura&quot;">​</a></h2><p>Al ejecutar Lertaro por primera vez, se instala e inicia un servicio de Windows en segundo plano (<code>Lertaro.Service</code>). Comprender este diseño te ayudará a aprovechar al máximo la herramienta:</p><ul><li><strong>Aplicación en primer plano (UI e interacción)</strong>: Renderiza las ventanas de búsqueda, paneles flotantes, menús de acción, interceptores de teclado y previsualizaciones instantáneas. Mantiene un uso mínimo de memoria y respuesta instantánea en milisegundos.</li><li><strong>Servicio en segundo plano (Indexación y datos)</strong>: Se ejecuta con privilegios de servicio en segundo plano, monitorizando los diarios de cambios USN de NTFS / ReFS, escuchando eventos en tiempo real de otros sistemas de archivos, gestionando recursos de red y manteniendo un árbol de índices ultrarrápido en memoria.</li><li><strong>Ventajas arquitectónicas</strong>: Reiniciar o actualizar la interfaz nunca borra el índice ni fuerza un reescaneo del disco. Las tareas pesadas de indexación nunca ralentizan tu escritura. Puedes comprobar el estado del servicio en cualquier momento en <a href="./settings/service-status.html"><strong>Configuración → Estado del servicio</strong></a>.</li></ul><h2 id="_3-tres-modalidades-de-ventana" tabindex="-1">3. Tres modalidades de ventana <a class="header-anchor" href="#_3-tres-modalidades-de-ventana" aria-label="Permalink to &quot;3. Tres modalidades de ventana&quot;">​</a></h2><p>Lertaro no se limita a una única ventana fija, sino que se adapta a tus flujos de trabajo con tres modalidades de ventana diseñadas a medida:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Modalidad de ventana</th><th style="text-align:left;">Activador predeterminado</th><th style="text-align:left;">Características clave y diseño</th><th style="text-align:left;">Escenario ideal</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Ventana rápida (Quick Window)</strong></td><td style="text-align:left;">Doble pulsación de <code>Ctrl</code> (personalizable)</td><td style="text-align:left;">Barra flotante centrada en pantalla, optimizada para memoria muscular, atajos numéricos y control total con teclado</td><td style="text-align:left;">Inicio frecuente de apps, búsqueda rápida de archivos, cálculos y traducciones</td></tr><tr><td style="text-align:left;"><strong>Ventana principal (Full Window)</strong></td><td style="text-align:left;">Barra de tareas/Menú Inicio, o <code>Ctrl+F</code></td><td style="text-align:left;">Ventana completa con vista de tabla para grandes volúmenes de resultados, filtros laterales, ordenación y Analizador de espacio</td><td style="text-align:left;">Exploración profunda de archivos, gestión masiva, limpieza de disco y filtrado avanzado</td></tr><tr><td style="text-align:left;"><strong>Ventana incrustada (Inline Window)</strong></td><td style="text-align:left;">Se incrusta automáticamente en diálogos o Explorador</td><td style="text-align:left;">Integrada perfectamente en diálogos de Windows y exploradores de archivos compatibles sin cambiar de contexto</td><td style="text-align:left;">Localización rápida de destinos al &quot;Abrir&quot; o &quot;Guardar como&quot; en software externo</td></tr></tbody></table><p>Las tres modalidades comparten exactamente el mismo motor de búsqueda, combinaciones de teclas, reglas de filtrado y menús de acción.</p><h2 id="_4-primera-busqueda-y-navegacion-basica" tabindex="-1">4. Primera búsqueda y navegación básica <a class="header-anchor" href="#_4-primera-busqueda-y-navegacion-basica" aria-label="Permalink to &quot;4. Primera búsqueda y navegación básica&quot;">​</a></h2><h3 id="escribe-para-buscar" tabindex="-1">Escribe para buscar <a class="header-anchor" href="#escribe-para-buscar" aria-label="Permalink to &quot;Escribe para buscar&quot;">​</a></h3><p>Abre la ventana de búsqueda y empieza a escribir. Los resultados aparecen en tiempo real con latencia de milisegundos. La búsqueda utiliza coincidencia difusa por defecto: los caracteres no necesitan ser consecutivos. Para consultar operadores y modificadores avanzados, consulta <a href="./search-syntax.html"><strong>Sintaxis de búsqueda</strong></a>.</p><h3 id="navegacion-y-apertura-de-resultados" tabindex="-1">Navegación y apertura de resultados <a class="header-anchor" href="#navegacion-y-apertura-de-resultados" aria-label="Permalink to &quot;Navegación y apertura de resultados&quot;">​</a></h3><ul><li><strong>Mover selección</strong>: Usa las flechas <code>↑</code> / <code>↓</code> (o las teclas de navegación configuradas <code>Ctrl+P</code> / <code>Ctrl+N</code>) para desplazarte por la lista.</li><li><strong>Abrir directamente</strong>: Pulsa <code>Enter</code> para abrir el archivo o iniciar la aplicación seleccionada.</li><li><strong>Mostrar en Explorador</strong>: Pulsa <code>Ctrl+Enter</code> para ubicar y seleccionar el elemento en el Explorador de archivos de Windows.</li><li><strong>Ejecutar como administrador</strong>: Pulsa <code>Ctrl+Shift+Enter</code> para ejecutar la aplicación con privilegios elevados.</li><li><strong>Salto numérico directo</strong>: En la Ventana rápida, pulsa <code>Ctrl</code> + <code>1</code>–<code>9</code> para abrir directamente cualquiera de los primeros 9 resultados.</li></ul><h3 id="menu-de-acciones-y-operaciones-avanzadas" tabindex="-1">Menú de acciones y operaciones avanzadas <a class="header-anchor" href="#menu-de-acciones-y-operaciones-avanzadas" aria-label="Permalink to &quot;Menú de acciones y operaciones avanzadas&quot;">​</a></h3><p>Pulsa <code>Ctrl+O</code> o la flecha derecha <code>→</code> en un elemento seleccionado para desplegar el <strong>Menú de acciones</strong>, que permite copiar rutas, ver propiedades, manipular archivos o invocar extensiones de plugins. Consulta <a href="./actions-and-preview.html"><strong>Acciones y vista previa</strong></a> y <a href="./hotkeys.html"><strong>Atajos de teclado</strong></a> para más detalles.</p>',23)])])}const g=a(r,[["render",n]]);export{m as __pageData,g as default};
